@Configuration @EnableMethodSecurity @EnableScheduling class FeatureSecurity {
 @Bean PasswordEncoder passwords(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService users(PasswordEncoder encoder,@Value("${demo.password:}") String password){if(password.isBlank())throw new IllegalStateException("Ustaw demo.password dla lokalnego ćwiczenia");String encoded=encoder.encode(password);return new InMemoryUserDetailsManager(User.withUsername("anna").password(encoded).roles("AGENT").build(),User.withUsername("piotr").password(encoded).roles("AGENT").build(),User.withUsername("admin").password(encoded).roles("ADMIN").build());}
 @Bean AuthenticationManager manager(UserDetailsService users,PasswordEncoder passwords){var provider=new DaoAuthenticationProvider();provider.setUserDetailsService(users);provider.setPasswordEncoder(passwords);return new ProviderManager(provider);}
 @Bean HttpSessionSecurityContextRepository contexts(){return new HttpSessionSecurityContextRepository();}
 @Bean HttpSessionCsrfTokenRepository csrfTokens(){return new HttpSessionCsrfTokenRepository();}
 @Bean SecurityFilterChain security(HttpSecurity http,AuthenticationManager manager,HttpSessionSecurityContextRepository contexts,HttpSessionCsrfTokenRepository tokens,ObjectMapper mapper)throws Exception {http.authenticationManager(manager).securityContext(config->config.securityContextRepository(contexts)).csrf(config->config.csrfTokenRepository(tokens)).requestCache(config->config.disable()).authorizeHttpRequests(config->config.requestMatchers("/api/auth/**").permitAll().requestMatchers("/api/tickets/*/watchers").hasRole("ADMIN").anyRequest().authenticated()).exceptionHandling(config->config.authenticationEntryPoint((request,response,error)->problem(response,mapper,401,"Zaloguj się")).accessDeniedHandler((request,response,error)->problem(response,mapper,403,"Brak dostępu do operacji")));return http.build();}
 static void problem(HttpServletResponse response,ObjectMapper mapper,int status,String message)throws IOException {response.setStatus(status);response.setContentType("application/problem+json");mapper.writeValue(response.getWriter(),org.springframework.http.ProblemDetail.forStatusAndDetail(HttpStatusCode.valueOf(status),message));}
 @Bean ApplicationRunner seedFeature(TicketService service,TicketRepository repository){return arguments->{if(repository.count()==0){service.create(new CreateTicketRequest("Obserwowany ticket","Zmień status w drugim oknie",Priority.NORMAL,null));service.create(new CreateTicketRequest("Drugi ticket demo","Ćwiczenie paginacji",Priority.HIGH,null));}};}
}
record UserDto(String login,String name,String role){} record LoginBody(@NotBlank String login,@NotBlank String password){}
@RestController @RequestMapping("/api/auth") class SessionEndpoints {
 private final AuthenticationManager manager;private final HttpSessionSecurityContextRepository contexts;private final HttpSessionCsrfTokenRepository tokens;
 SessionEndpoints(AuthenticationManager manager,HttpSessionSecurityContextRepository contexts,HttpSessionCsrfTokenRepository tokens){this.manager=manager;this.contexts=contexts;this.tokens=tokens;}
 private UserDto user(Authentication authentication){boolean admin=authentication.getAuthorities().stream().anyMatch(role->role.getAuthority().equals("ROLE_ADMIN"));return new UserDto(authentication.getName(),authentication.getName(),admin?"admin":"agent");}
 @GetMapping("/csrf") Map<String,String> csrf(CsrfToken token){return Map.of("headerName",token.getHeaderName(),"token",token.getToken());}
 @GetMapping("/me") ResponseEntity<?> me(Authentication authentication){if(authentication==null||authentication instanceof AnonymousAuthenticationToken)return ResponseEntity.status(401).body(ProblemDetail.forStatusAndDetail(HttpStatus.UNAUTHORIZED,"Brak sesji"));return ResponseEntity.ok(user(authentication));}
 @PostMapping("/login") ResponseEntity<?> login(@Valid @RequestBody LoginBody body,HttpServletRequest request,HttpServletResponse response){try{Authentication authentication=manager.authenticate(UsernamePasswordAuthenticationToken.unauthenticated(body.login().trim(),body.password()));new ChangeSessionIdAuthenticationStrategy().onAuthentication(authentication,request,response);new CsrfAuthenticationStrategy(tokens).onAuthentication(authentication,request,response);var context=SecurityContextHolder.createEmptyContext();context.setAuthentication(authentication);SecurityContextHolder.setContext(context);contexts.saveContext(context,request,response);return ResponseEntity.ok(user(authentication));}catch(AuthenticationException error){return ResponseEntity.status(401).body(ProblemDetail.forStatusAndDetail(HttpStatus.UNAUTHORIZED,"Błędny login lub hasło"));}}
 @PostMapping("/logout") ResponseEntity<Void> logout(HttpServletRequest request,HttpServletResponse response,Authentication authentication){new CsrfLogoutHandler(tokens).logout(request,response,authentication);new SecurityContextLogoutHandler().logout(request,response,authentication);new CookieClearingLogoutHandler("SESSION").logout(request,response,authentication);return ResponseEntity.noContent().build();}
}
@Entity @Table(name="ticket_watch",uniqueConstraints=@UniqueConstraint(columnNames={"user_login","ticket_id"})) class WatchEntity {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(name="user_login",nullable=false) String userLogin;@Column(name="ticket_id",nullable=false) long ticketId;protected WatchEntity(){}WatchEntity(String user,long ticket){userLogin=user;ticketId=ticket;}}
@Entity @Table(name="user_notification",indexes=@Index(columnList="user_login,id")) class NotificationEntity {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(name="user_login",nullable=false) String userLogin;long ticketId;String text;Instant createdAt;@Column(name="is_read",nullable=false) boolean read;protected NotificationEntity(){}}
@Entity class CommentEntity {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;long ticketId;String userLogin;@Column(length=1000) String text;Instant createdAt;protected CommentEntity(){}}
interface WatchRepository extends JpaRepository<WatchEntity,Long>{Optional<WatchEntity> findByUserLoginAndTicketId(String user,long ticket);List<WatchEntity> findByTicketId(long ticket);long countByTicketId(long ticket);org.springframework.data.domain.Page<WatchEntity> findByUserLogin(String user,Pageable pageable);void deleteByTicketId(long ticket);}
interface NotificationRepository extends JpaRepository<NotificationEntity,Long>{List<NotificationEntity> findByUserLoginOrderByIdDesc(String user);@Modifying(clearAutomatically=true,flushAutomatically=true) @org.springframework.data.jpa.repository.Query("update NotificationEntity n set n.read=true where n.userLogin=:user and n.id<=:through") int markThrough(@Param("user") String user,@Param("through") long through);}
interface CommentRepository extends JpaRepository<CommentEntity,Long>{}
record WatchStatus(boolean watching,long count){} record NotificationDto(long id,long ticketId,String text,Instant createdAt,boolean read){}
record ReadAllBody(@NotNull @PositiveOrZero @Max(9007199254740991L) Long throughId){} record CommentBody(@NotBlank @Size(max=1000) String text){}
record TicketChanged(long ticketId,String actor,String text,List<String> recipients){} record Delivery(String user,NotificationDto notification){} record NotificationsCommitted(List<Delivery> deliveries){}
@Service @Transactional class WatchService {
 private final EntityManager manager;private final WatchRepository watches;private final NotificationRepository notifications;private final CommentRepository comments;private final TicketService tickets;private final ApplicationEventPublisher events;
 WatchService(EntityManager manager,WatchRepository watches,NotificationRepository notifications,CommentRepository comments,TicketService tickets,ApplicationEventPublisher events){this.manager=manager;this.watches=watches;this.notifications=notifications;this.comments=comments;this.tickets=tickets;this.events=events;}
 private TicketEntity locked(long id){if(id<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Nieprawidłowe ID");TicketEntity ticket=manager.find(TicketEntity.class,id,LockModeType.PESSIMISTIC_WRITE);if(ticket==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Nie znaleziono ticketu");return ticket;}
 WatchStatus status(String user,long id){locked(id);return new WatchStatus(watches.findByUserLoginAndTicketId(user,id).isPresent(),watches.countByTicketId(id));}
 WatchStatus set(String user,long id,boolean desired){locked(id);var existing=watches.findByUserLoginAndTicketId(user,id);if(desired&&existing.isEmpty())watches.saveAndFlush(new WatchEntity(user,id));if(!desired&&existing.isPresent()){watches.delete(existing.get());watches.flush();}return new WatchStatus(desired,watches.countByTicketId(id));}
 @PreAuthorize("hasRole('ADMIN')") List<String> watchers(long id){locked(id);return watches.findByTicketId(id).stream().map(watch->watch.userLogin).sorted().toList();}
 PageDto<TicketDto> watched(String user,int page,int size){if(page<1||size<1||size>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Nieprawidłowa paginacja");var result=watches.findByUserLogin(user,PageRequest.of(page-1,size,Sort.by("id").descending()));return new PageDto<>(result.getContent().stream().map(watch->tickets.get(watch.ticketId)).toList(),result.getTotalElements(),page,size);}
 private NotificationDto dto(NotificationEntity value){return new NotificationDto(value.id,value.ticketId,value.text,value.createdAt,value.read);}
 List<NotificationDto> notifications(String user,boolean unreadOnly){return notifications.findByUserLoginOrderByIdDesc(user).stream().filter(notification->!unreadOnly||!notification.read).map(this::dto).toList();}
 List<NotificationDto> readThrough(String user,long through){notifications.markThrough(user,through);return notifications(user,false);}
 private void changed(long id,String actor,String text){events.publishEvent(new TicketChanged(id,actor,text,watches.findByTicketId(id).stream().map(watch->watch.userLogin).toList()));}
 TicketDto patch(long id,String actor,JsonNode body){TicketEntity ticket=locked(id);if(!body.isObject()||body.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Brak zmian");for(var fields=body.fieldNames();fields.hasNext();)if(!Set.of("status","assignee","priority","title").contains(fields.next()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Nieznane pole");boolean altered=false;
 if(body.has("status")){if(!body.get("status").isTextual())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Status");TicketStatus status;try{status=TicketStatus.valueOf(body.get("status").asText());}catch(IllegalArgumentException error){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Status");}altered|=ticket.status!=status;ticket.status=status;}
 if(body.has("priority")){if(!body.get("priority").isTextual())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Priority");Priority priority;try{priority=Priority.valueOf(body.get("priority").asText());}catch(IllegalArgumentException error){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Priority");}altered|=ticket.priority!=priority;ticket.priority=priority;}
 if(body.has("title")){if(!body.get("title").isTextual())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Tytuł");String title=body.get("title").asText().trim();if(title.length()<5||title.length()>120)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Tytuł");altered|=!Objects.equals(title,ticket.title);ticket.title=title;}
 if(body.has("assignee")){JsonNode value=body.get("assignee");if(!value.isNull()&&!value.isTextual())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Przypisanie");String assignee=value.isNull()?null:value.asText();if(assignee!=null&&assignee.length()>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Przypisanie");altered|=!Objects.equals(ticket.assignee,assignee);ticket.assignee=assignee;}
 if(altered)changed(id,actor,"Zmieniono ticket #"+id);return new TicketDto(ticket.id,ticket.title,ticket.description,ticket.status,ticket.priority,ticket.assignee,ticket.createdAt,List.copyOf(ticket.tags));}
 void comment(long id,String actor,String text){locked(id);var comment=new CommentEntity();comment.ticketId=id;comment.userLogin=actor;comment.text=text.trim();if(comment.text.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Pusty komentarz");comment.createdAt=Instant.now();comments.save(comment);changed(id,actor,"Nowy komentarz w tickecie #"+id);}
 void deleteTicket(long id,String actor){TicketEntity ticket=locked(id);changed(id,actor,"Usunięto ticket #"+id);watches.deleteByTicketId(id);manager.remove(ticket);}
}
@Service class NotificationCreation {private final NotificationRepository notifications;private final ApplicationEventPublisher events;NotificationCreation(NotificationRepository notifications,ApplicationEventPublisher events){this.notifications=notifications;this.events=events;}
 @TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT) @Transactional(propagation=Propagation.REQUIRES_NEW) public void create(TicketChanged event){var deliveries=new ArrayList<Delivery>();for(String user:new LinkedHashSet<>(event.recipients())){if(user.equals(event.actor()))continue;var value=new NotificationEntity();value.userLogin=user;value.ticketId=event.ticketId();value.text=event.text();value.createdAt=Instant.now();value.read=false;notifications.saveAndFlush(value);deliveries.add(new Delivery(user,new NotificationDto(value.id,value.ticketId,value.text,value.createdAt,false)));}events.publishEvent(new NotificationsCommitted(List.copyOf(deliveries)));}
}
@Component class NotificationStreams {private final ConcurrentMap<String,Set<SseEmitter>> channels=new ConcurrentHashMap<>();SseEmitter subscribe(String user){var emitter=new SseEmitter(300000L);var set=channels.computeIfAbsent(user,key->new CopyOnWriteArraySet<>());set.add(emitter);Runnable remove=()->{set.remove(emitter);if(set.isEmpty())channels.remove(user,set);};emitter.onCompletion(remove);emitter.onTimeout(remove);emitter.onError(error->remove.run());return emitter;}
 @TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT) public void send(NotificationsCommitted event){for(Delivery delivery:event.deliveries()){var set=channels.get(delivery.user());if(set==null)continue;for(SseEmitter emitter:set){try{emitter.send(SseEmitter.event().id(Long.toString(delivery.notification().id())).name("notification").data(delivery.notification()));}catch(Exception error){set.remove(emitter);emitter.complete();}}}}
 @Scheduled(fixedDelay=15000) public void heartbeat(){channels.forEach((user,set)->{for(SseEmitter emitter:set)try{emitter.send(SseEmitter.event().comment("keepalive"));}catch(Exception error){set.remove(emitter);emitter.complete();}if(set.isEmpty())channels.remove(user,set);});}
}
@RestController class WatchEndpoints {private final WatchService service;private final NotificationStreams streams;WatchEndpoints(WatchService service,NotificationStreams streams){this.service=service;this.streams=streams;}
 @GetMapping("/api/tickets/{id}/watch") WatchStatus status(Authentication auth,@PathVariable("id") long id){return service.status(auth.getName(),id);}
 @PutMapping("/api/tickets/{id}/watch") WatchStatus watch(Authentication auth,@PathVariable("id") long id){return service.set(auth.getName(),id,true);}
 @DeleteMapping("/api/tickets/{id}/watch") WatchStatus unwatch(Authentication auth,@PathVariable("id") long id){return service.set(auth.getName(),id,false);}
 @GetMapping("/api/tickets/{id}/watchers") @PreAuthorize("hasRole('ADMIN')") List<String> watchers(@PathVariable("id") long id){return service.watchers(id);}
 @GetMapping("/api/me/watched") PageDto<TicketDto> watched(Authentication auth,@RequestParam(name="page",defaultValue="1") int page,@RequestParam(name="pageSize",defaultValue="10") int size){return service.watched(auth.getName(),page,size);}
 @GetMapping("/api/me/notifications") List<NotificationDto> notifications(Authentication auth,@RequestParam(name="unreadOnly",defaultValue="false") boolean unreadOnly){return service.notifications(auth.getName(),unreadOnly);}
 @PostMapping("/api/me/notifications/read-all") List<NotificationDto> readAll(Authentication auth,@Valid @RequestBody ReadAllBody body){return service.readThrough(auth.getName(),body.throughId());}
 @GetMapping(path="/api/me/events",produces=MediaType.TEXT_EVENT_STREAM_VALUE) SseEmitter events(Authentication auth){return streams.subscribe(auth.getName());}
 @PatchMapping("/api/tickets/{id}") TicketDto patch(Authentication auth,@PathVariable("id") long id,@RequestBody JsonNode body){return service.patch(id,auth.getName(),body);}
 @PostMapping("/api/tickets/{id}/comments") ResponseEntity<Void> comment(Authentication auth,@PathVariable("id") long id,@Valid @RequestBody CommentBody body){service.comment(id,auth.getName(),body.text());return ResponseEntity.noContent().build();}
 @DeleteMapping("/api/tickets/{id}") @PreAuthorize("hasRole('ADMIN')") ResponseEntity<Void> delete(Authentication auth,@PathVariable("id") long id){service.deleteTicket(id,auth.getName());return ResponseEntity.noContent().build();}
}
